-- Demo data (SEED_DEMO_DATA=true). Branch / account IDs must match branch-service and identity seeds.
-- B1 = 11111111-...  Chi nhánh Quận 1
-- B2 = 22222222-...  Chi nhánh Thủ Đức
-- B3 = 33333333-...  Chi nhánh Bình Thạnh
START TRANSACTION;




SELECT UUID(), warehouse_id, ingredient_id, quantity, quantity, 'SEED', warehouse_id, 'system'
FROM stock_balances;

-- DP-DEMO-0001: Q1 requests Gạo 20 + Bò 5 -> only "Kho tổng Thủ Đức" has the full list.
