UPDATE transfer_requests
   SET status = 'APPROVED', supplier_branch_id = '22222222-2222-4222-8222-222222222222',
       supplier_warehouse_id = 'b0000000-0000-4000-8000-000000000003',
       approved_by = 'f0000000-0000-4000-8000-000000000001', approved_at = '2026-10-21 01:15:00.000', version = version + 1
 WHERE id = 'c0000000-0000-4000-8000-000000000003';

